// Essaim (curseur animé) : état poussé par l'appli (à chaque changement et au moins toutes les
// 2 s), pause, presets. Les presets demandent Essaim 0.13 (`preset` dans l'état) ; avec une
// version d'avant, il reste la pause et l'ouverture de config.toml.
const essaim = horizon.connect("ws://127.0.0.1:28670");
let id = 0;
let etat = null; // dernier état reçu ; null : Essaim absent
let presets = []; // [{ name, builtin, active }]
let demande = 0; // identifiant de la dernière demande de liste
let demandeLe = 0;

function commande(cmd, args) {
  essaim.send(Object.assign({ id: ++id, cmd }, args || {}));
  return id;
}

const avecPresets = () => !!etat && "preset" in etat;

function lister() {
  if (!avecPresets()) return;
  demande = commande("list_presets");
  demandeLe = Date.now();
}

// 1 en pause, 2 en veille (plein écran), 3 actif ; la pause l'emporte.
function code() {
  if (!etat) return 0;
  if (etat.paused) return 1;
  return etat.fullscreen || !etat.active ? 2 : 3;
}

function montrer() {
  const c = code();
  horizon.ui.set("connecte", c !== 0);
  horizon.ui.set("etat", c);
  horizon.ui.set("etat-texte", ["", "En pause", "En veille (plein écran)", "Actif"][c]);
  horizon.ui.set(
    "detail",
    etat
      ? (etat.gpu ? "Dessin par la carte graphique" : "Dessin par le processeur (secours)") +
          (etat.prisme ? " · couleur synchronisée sur Prisme" : "")
      : "",
  );
  horizon.ui.set("fenetre", avecPresets());
  horizon.ui.set("presets", presets.map((p) => ({ nom: p.name, fourni: !!p.builtin, actif: !!p.active })));
  horizon.palette.set(
    c === 0
      ? []
      : [{ id: "pause", label: c === 1 ? "Reprendre" : "Mettre en pause", icon: c === 1 ? "play" : "pause" }].concat(
          presets.slice(0, 48).map((p) => ({ id: "preset:" + p.name, label: "Preset " + p.name, icon: "atom" })),
        ),
  );
}

function basculer() {
  if (etat) commande("set_paused", { paused: !etat.paused });
}

function choisir(nom) {
  if (!etat) return;
  commande("apply_preset", { name: nom });
  // Coche tout de suite ; Essaim confirme par son état (la liste est alors redemandée).
  presets = presets.map((p) => Object.assign({}, p, { active: p.name === nom }));
  montrer();
}

essaim.onState((s) => {
  if (s === "closed") {
    etat = null;
    presets = [];
    montrer();
  }
});

essaim.onMessage((texte) => {
  let m;
  try {
    m = JSON.parse(texte);
  } catch (e) {
    return;
  }
  if (m.event === "state") {
    const avant = etat;
    etat = m.data || {};
    if (!avant || avant.preset !== etat.preset) lister();
    montrer();
    return;
  }
  if (m.ok === false) {
    horizon.log.warn("Essaim :", texte);
    return;
  }
  if (m.id === demande && Array.isArray(m.data)) {
    presets = m.data.filter((p) => p && typeof p.name === "string");
    montrer();
  }
});

horizon.ui.on("basculer", basculer);
horizon.ui.on("choisir", (inst, nom) => choisir(nom));
horizon.ui.on("ouvrir", () => {
  if (etat) commande(avecPresets() ? "open_settings" : "open_config");
});
// Panneau montré : un preset enregistré ou supprimé dans Essaim se voit dans les 5 s.
horizon.ui.on("tic", () => {
  if (Date.now() - demandeLe >= 5000) lister();
});
horizon.palette.on((cle) => {
  if (cle === "pause") basculer();
  else if (cle.startsWith("preset:")) choisir(cle.slice(7));
});

// Essaim ferme un client muet depuis 60 s : une demande toutes les 25 s garde la connexion.
horizon.timer.every(25000, () => {
  if (!etat) return;
  if (avecPresets()) lister();
  else commande("get_state");
});

montrer();

files.panel.slint:
// Panneau : pause ou reprise, état, presets (celui en place coché), ouvrir Essaim. Les réglages
// fins restent dans la fenêtre d'Essaim.
import { PanelBase, ListRow, Theme } from "@horizon";

export struct Preset {
    nom: string,
    // Fourni avec Essaim (sinon : enregistré par l'utilisateur).
    fourni: bool,
    actif: bool,
}

// Colonne qui défile au-delà de `limite` (molette), avec son repère à droite.
component Defilement inherits Rectangle {
    in property <length> limite: 288px;
    property <length> contenu: colonne.preferred-height;
    min-height: min(root.contenu, root.limite);
    preferred-height: self.min-height;
    max-height: self.min-height;
    vue := Flickable {
        content-width: self.width;
        content-height: root.contenu;
        colonne := VerticalLayout {
            x: 0;
            y: 0;
            width: vue.width;
            height: root.contenu;
            @children
        }
    }
    if root.contenu > root.limite: Rectangle {
        x: root.width - 4px;
        y: -vue.content-y / root.contenu * root.height;
        width: 4px;
        height: max(16px, root.height * root.height / root.contenu);
        border-radius: 2px;
        background: Theme.track;
    }
}

export component Panel inherits Window {
    in property <bool> connecte;
    in property <int> etat;
    // « Actif », « En pause »… et la ligne du dessous (moteur de dessin, synchro Prisme).
    in property <string> etat-texte;
    in property <string> detail;
    in property <[Preset]> presets;
    // Essaim sait ouvrir sa fenêtre de réglages (sinon : son fichier de configuration).
    in property <bool> fenetre;
    callback basculer();
    callback choisir(string);
    callback ouvrir();
    // Chaque seconde tant que le panneau est montré : la liste des presets est redemandée.
    callback tic();
    background: transparent;

    Timer {
        interval: 1s;
        running: true;
        triggered => { root.tic(); }
    }

    PanelBase {
        title: "Essaim";
        if !root.connecte: Text {
            text: "Essaim n’est pas lancé.";
            color: Theme.text-dim;
            font-size: Theme.fs-body;
        }
        if root.connecte: ListRow {
            icon: root.etat == 1 ? "play" : "pause";
            title: root.etat == 1 ? "Reprendre" : "Mettre en pause";
            subtitle: root.etat-texte;
            clicked => { root.basculer(); }
        }
        if root.connecte && root.detail != "": Text {
            text: root.detail;
            color: Theme.text-dim;
            font-size: Theme.fs-meta;
            wrap: word-wrap;
        }
        if root.presets.length > 0: Text {
            text: "PRESETS";
            color: Theme.text-dim;
            font-size: Theme.fs-meta;
            font-weight: 600;
        }
        // Une vingtaine de presets fournis : la liste défile au lieu d'allonger le panneau.
        if root.presets.length > 0: Defilement {
            for p in root.presets: ListRow {
                icon: p.actif ? "check" : p.fourni ? "sparkle" : "pencilSimple";
                title: p.nom;
                clicked => { root.choisir(p.nom); }
            }
        }
        if root.connecte: ListRow {
            icon: "arrowSquareOut";
            title: root.fenetre ? "Ouvrir Essaim" : "Ouvrir config.toml";
            subtitle: root.fenetre ? "Réglages et presets" : "Essaim 0.13 ou plus récent : presets et réglages ici";
            clicked => { root.ouvrir(); }
        }
    }
}

files.widget.slint:
// Essaim : un atome, coloré quand le curseur est animé ; en pause ou en veille, un petit signe à
// côté. Clic : pause ou reprise. Essaim absent : le widget ne prend pas de place.
import { Island, Icon, Theme } from "@horizon";

export component Widget inherits Window {
    in property <bool> connecte;
    // 1 en pause, 2 en veille (plein écran), 3 actif.
    in property <int> etat;
    out property <bool> own-clicks: true;
    callback basculer();
    background: transparent;

    VerticalLayout {
        alignment: center;
        if root.connecte: Island {
            gap: 4px;
            Icon {
                name: "atom";
                size: 15px;
                color: root.etat == 3 ? Theme.accent : Theme.text-dim;
                y: (parent.height - self.height) / 2;
            }
            if root.etat == 1 || root.etat == 2: Icon {
                name: root.etat == 1 ? "pause" : "moonFill";
                size: 10px;
                color: Theme.text-dim;
                y: (parent.height - self.height) / 2;
            }
        }
    }
    TouchArea {
        mouse-cursor: pointer;
        clicked => { root.basculer(); }
    }
}
